using Flagman;using Microsoft.Data.Sqlite;using System.Security.Cryptography;using System.Text;using System.Text.Json;
public static class MigrationCopyChecks
{
 static string Digest(string path){using var db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=path,Mode=SqliteOpenMode.ReadOnly}.ToString());db.Open();var text=new StringBuilder();foreach(var table in new[]{"batches","deliveries","orders","movements"}){using var cmd=db.CreateCommand();cmd.CommandText=$"SELECT id,payload FROM {table} ORDER BY id";using var r=cmd.ExecuteReader();while(r.Read())text.Append(table).Append(r.GetString(0)).Append(table switch{"batches"=>JsonSerializer.Serialize(JsonSerializer.Deserialize<Batch>(r.GetString(1),Store.Json),Store.Json),"movements"=>JsonSerializer.Serialize(JsonSerializer.Deserialize<Movement>(r.GetString(1),Store.Json),Store.Json),"orders"=>JsonSerializer.Serialize(JsonSerializer.Deserialize<Order>(r.GetString(1),Store.Json),Store.Json),_=>JsonSerializer.Serialize(JsonSerializer.Deserialize<Delivery>(r.GetString(1),Store.Json),Store.Json)});}return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text.ToString())));}
 public static void Run(string source,string target){Store.BackupFile(source,target);var before=Digest(target);var store=new Store(target);store.VerifyIntegrity();WorkflowChecks.Check(Digest(target)==before,"Migration changed legacy documents");store.Write(s=>Inventory.Expire(s,s.Now(DateTimeOffset.UtcNow)));new Store(target).Write(s=>Inventory.Expire(s,s.Now(DateTimeOffset.UtcNow)));WorkflowChecks.Check(Digest(target)==before,"Monitor changed physical stock");string backup=target+".verified-backup.db",restore=target+".restored.db";store.Backup(backup);Store.BackupFile(backup,restore);new Store(restore).VerifyIntegrity();WorkflowChecks.Check(Digest(restore)==before,"Restore changed original documents");Console.WriteLine("PASS Working_database_copy_migration_restart_backup_restore_preserves_original_documents");}
}
